{
  "reply": "先确定定义域：x≠-2。分子在x=3时为0，分母在x=-2时为0。以-2、3分段：当x<-2时，分子、分母都为负，分式为正；当-2<x<3时，分子为负、分母为正，分式为负；当x>3时，两者都为正。x=3使分式等于0，可以取到；x=-2使分母为0，必须排除。因此解集为(-∞,-2)∪[3,+∞)。",
  "result": {
    "status": "solved",
    "problem": {
      "statement": "解不等式 (x-3)/(x+2)≥0。",
      "topic": "分式不等式",
      "subtopics": ["定义域", "分段判断符号", "端点取舍"],
      "givens": ["(x-3)/(x+2)≥0"],
      "variables": ["x：实数未知数"],
      "constraints": ["x≠-2"],
      "goal": "求不等式的实数解集。",
      "requested_method": null,
      "ambiguities": [],
      "assumptions": []
    },
    "plan": {
      "main_idea": "以分子和分母的零点划分区间，判断各区间内分式的符号。",
      "method": "分区间讨论符号",
      "prerequisites": ["分母不能为0", "同号相除为正，异号相除为负"],
      "steps": ["确定定义域和关键点。", "判断三个区间内分式的符号。", "检查端点并写出解集。"]
    },
    "solution": {
      "derivation": [
        {
          "step": 1,
          "expression": "x+2≠0，即x≠-2；x-3=0时，x=3。",
          "justification": "分母不能为0；分子为0且分母不为0时，分式等于0。"
        },
        {
          "step": 2,
          "expression": "x<-2时，x-3<0，x+2<0，所以(x-3)/(x+2)>0。",
          "justification": "分子与分母同为负数，相除为正。"
        },
        {
          "step": 3,
          "expression": "-2<x<3时，x-3<0，x+2>0，所以(x-3)/(x+2)<0。",
          "justification": "分子与分母异号，相除为负。"
        },
        {
          "step": 4,
          "expression": "x>3时，x-3>0，x+2>0，所以(x-3)/(x+2)>0。",
          "justification": "分子与分母同为正数，相除为正。"
        },
        {
          "step": 5,
          "expression": "x=3时，(x-3)/(x+2)=0；解集为(-∞,-2)∪[3,+∞)。",
          "justification": "不等号包含等号，因此保留x=3；x=-2不在定义域内，必须排除。结合各区间的符号得到解集。"
        }
      ],
      "answer": "(-∞,-2)∪[3,+∞)",
      "conditions": ["在实数范围内求解，且x≠-2。"]
    },
    "verification": {
      "status": "passed",
      "checks": [
        {
          "name": "乘以正数进行等价核验",
          "status": "passed",
          "details": "在x≠-2时，(x+2)²>0，两边同乘它，原不等式等价于(x-3)(x+2)≥0。两因子同为非负数得到x≥3；同为非正数得到x≤-2。再排除x=-2，得到x<-2或x≥3，与所得解集一致。"
        },
        {
          "name": "端点代回",
          "status": "passed",
          "details": "x=3时原分式为0/5=0，满足不等式；x=-2时分母为0，原分式无意义。因此3取闭端点，-2取开端点。"
        }
      ],
      "issues": []
    },
    "teaching_notes": {
      "key_insight": "先排除分母的零点，再用分子、分母的零点划分符号区间。",
      "difficult_steps": ["区分分子零点与分母零点的端点取舍。"],
      "common_mistakes": ["直接乘以x+2却不讨论其正负。", "把x=-2包含在解集中。", "漏掉使分式等于0的x=3。"],
      "prerequisite_explanations": ["不等式两边同乘负数时，不等号方向必须改变；同乘正数时方向不变。"],
      "alternative_method": "在定义域内，两边同乘恒正的(x+2)²，转化为(x-3)(x+2)≥0，再求解。",
      "follow_up_exercise_suggestion": null
    }
  }
}

